import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { stripTypeScriptTypes } from 'node:module';
const source = stripTypeScriptTypes(await readFile(new URL('../../apps/mobile/src/guideSnapshot.ts', import.meta.url), 'utf8'));
const { guideRows, parseGuideSnapshot, guideMaxChars } = await import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
const now = Date.now();
const guide = { id: 'tim-help', operadora: 'TIM', topico: 'sinal', titulo: 'Consulte sua cobertura', resumo: 'Consulte o canal oficial para sua região.', passos: ['Abra o atendimento oficial.'], fonte: 'https://www.tim.com.br/ajuda', canalOficial: 'https://www.tim.com.br/ajuda', revisadoEm: new Date(now - 86400000).toISOString(), validoAte: new Date(now + 86400000).toISOString(), responsavelId: 'must-not-persist' };
const raw = data => JSON.stringify({ version: 1, storeId: 'vox', savedAt: now, guides: [guide], ...data });
assert.equal(parseGuideSnapshot(raw({}), now).guides[0].titulo, guide.titulo);
assert.equal('responsavelId' in guideRows([guide], now)[0], false);
assert.equal(guideRows(Array.from({ length: 200 }, () => guide), now).length, 100);
assert.equal(guideRows([{ ...guide, validoAte: new Date(now - 1).toISOString() }], now).length, 0);
for (const change of [{ operadora: '__proto__' }, { fonte: 'https://tim.com.br.evil.invalid/ajuda' }, { fonte: 'https://user:password@tim.com.br/ajuda' }, { canalOficial: 'http://tim.com.br/ajuda' }, { fonte: 'https://tim.com.br:444/ajuda' }, { passos: ['x'.repeat(601)] }, { revisadoEm: new Date(now + 1).toISOString() }, { validoAte: 'invalid' }, { validoAte: new Date(now + 181 * 86400000).toISOString() }]) assert.throws(() => guideRows([{ ...guide, ...change }], now));
for (const change of [{ version: 2 }, { savedAt: now + 1 }, { savedAt: now - 49 * 3600000 }, { storeId: '' }]) assert.throws(() => parseGuideSnapshot(raw(change), now));
assert.throws(() => parseGuideSnapshot('x'.repeat(guideMaxChars + 1), now));
const fixture = globalThis.__voxGuideFixture = { stored: null, error: null, failStorage: false, rows: [guide] };
let loader = stripTypeScriptTypes(await readFile(new URL('../../apps/mobile/src/offlineGuides.ts', import.meta.url), 'utf8'));
loader = loader.replace(/import .* from '@react-native-async-storage\/async-storage';/, `const AsyncStorage = { getItem: async () => globalThis.__voxGuideFixture.stored, setItem: async (key, value) => { if (globalThis.__voxGuideFixture.failStorage) throw new Error('Full'); globalThis.__voxGuideFixture.stored = value; }, removeItem: async () => { globalThis.__voxGuideFixture.stored = null; } };`);
loader = loader.replace(/import .* from '\.\/api';/, `export class ApiError extends Error { constructor(message, status) { super(message); this.status = status; } } const publicApiIdentity = 'https://fixture.invalid/api'; const request = async path => { const f = globalThis.__voxGuideFixture; if (f.error) throw f.error; return path === '/loja' ? { id: 'vox' } : f.rows; };`);
loader = loader.replace(/from '\.\/guideSnapshot'/, `from 'data:text/javascript;base64,${Buffer.from(source).toString('base64')}'`);
const { loadGuides, ApiError } = await import(`data:text/javascript;base64,${Buffer.from(loader).toString('base64')}`);
assert.equal((await loadGuides()).savedAt, null);
assert.equal(fixture.stored.includes('must-not-persist'), false);
fixture.error = new TypeError('Offline');
assert.equal((await loadGuides()).guides[0].id, guide.id);
fixture.stored = raw({ guides: [{ ...guide, validoAte: new Date(now - 1).toISOString() }] });
assert.equal((await loadGuides()).guides.length, 0);
fixture.error = new ApiError('Missing', 404);
await assert.rejects(loadGuides(), error => error.status === 404);
fixture.error = new TypeError('Offline'); fixture.stored = raw({ savedAt: now - 49 * 3600000 });
await assert.rejects(loadGuides()); assert.equal(fixture.stored, null);
fixture.error = null; fixture.failStorage = true;
assert.equal((await loadGuides()).guides.length, 1); assert.equal(fixture.stored, null);
delete globalThis.__voxGuideFixture;
console.log('Offline guides: public bounded fields, official URLs, editorial expiry, network fallback, 404 refusal and storage failure passed.');
